'use strict'

const Fastify = require('./fastify')

async function main () {
  const fastify = Fastify()
  fastify.addSchema({
    $id: 'MyModel',
    type: 'object',
    properties: {
      length: { anyOf: [{ type: 'null' }, { type: 'number' }] },
      tags: { type: 'array', items: { oneOf: [{ type: 'null' }, { type: 'string' }] } },
      keep: { anyOf: [{ type: 'null' }, { type: 'number', minimum: 5 }] }
    }
  })
