'use strict'

const Ajv = require('ajv')
const opts = { coerceTypes: 'array', useDefaults: true, removeAdditional: true, addUsedSchema: false, allErrors: false }

function run (name, sub, values) {
  const ajv = new Ajv(opts)
  const v = ajv.compile({ type: 'object', properties: { length: sub } })
  for (const val of values) {
    const data = { length: val }
    const ok = v(data)
    console.log(name, '| in:', JSON.stringify(val), '| ok:', ok, '| out:', JSON.stringify(data.length))
  }
}

const vals = [0, null, 1, '2', 'x', false, '']

run('anyOf null-first ', { anyOf: [{ type: 'null' }, { type: 'number' }] }, vals)
run('anyOf num-first  ', { anyOf: [{ type: 'number' }, { type: 'null' }] }, vals)
run('union type       ', { type: ['number', 'null'] }, vals)
run('oneOf null-first ', { oneOf: [{ type: 'null' }, { type: 'number' }] }, vals)

